57	function TripDateBadge({ start, end }: { start: string; end: string }) {
58	  const today = new Date();
59	  today.setHours(0, 0, 0, 0);
60	  const startDate = new Date(start);
61	  const endDate = new Date(end);
62	
63	  let tone = "bg-[#eef1ff] text-[#546dfe]"; // upcoming
64	  if (endDate < today) tone = "bg-[#f0f2f5] text-slate-500"; // past
65	  else if (startDate <= today) tone = "bg-[#e8fbf1] text-[#14a05a]"; // in progress
66	
67	  const fmt = (d: string) =>
68	    new Date(d).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
69	
70	  return (
71	    <span className={cn("inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-xs font-semibold", tone)}>
72	      <Calendar className="h-3 w-3" />
73	      {fmt(start)} – {fmt(end)}
74	    </span>
75	  );
76	}
